#!/usr/bin/env python3
"""Generate dictionary lookup ranges from the pinned Unicode 16.0.0 database."""
import argparse
import hashlib
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('unicode_data', type=Path)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    source = args.unicode_data.read_bytes()
    if hashlib.sha256(source).hexdigest() != 'ff58e5823bd095166564a006e47d111130813dcf8bf234ef79fa51a870edb48f':
        parser.error('Expected the official Unicode 16.0.0 UnicodeData.txt')
    ranges = []
    first = None
    for line in source.decode('utf-8').splitlines():
        fields = line.split(';')
        scalar = int(fields[0], 16)
        if fields[1].endswith(', First>'):
            first = scalar
            continue
        begin = first if first is not None else scalar
        first = None
        if fields[2][0] not in 'LMN':
            continue
        if ranges and begin == ranges[-1][1] + 1:
            ranges[-1][1] = scalar
        else:
            ranges.append([begin, scalar])
    output = ('// SPDX-License-Identifier: Unicode-3.0\n'
              '// Copyright © 1991-2026 Unicode, Inc.\n'
              '// Generated by generate.py from Unicode 16.0.0 categories L*, M*, N*.\n')
    output += ''.join(f'{{0x{begin:06x}, 0x{end:06x}}},\n' for begin, end in ranges)
    target = Path(__file__).with_name('lookup_ranges.inc')
    if args.check:
        if target.read_text() != output:
            parser.error('lookup_ranges.inc differs from the pinned database')
    else:
        target.write_text(output)


if __name__ == '__main__':
    main()
